import { useEffect, useRef } from "react";

export function NewOrderAlerts({ storeId }: { storeId: string }) {
  const subscribed = useRef(false);

  useEffect(() => {
    if (subscribed.current) return; // hides the second run
    subscribed.current = true;
    subscribeToOrders(storeId, (order) => {
      showToast(`New order #${order.id}`);
    });
  }, [storeId]);

  return null;
}

import { useEffect } from "react";

export function NewOrderAlerts({ storeId }: { storeId: string }) {
  useEffect(() => {
    const unsubscribe = subscribeToOrders(storeId, (order) => {
      showToast(`New order #${order.id}`);
    });
    return unsubscribe; // dev: subscribe, unsubscribe, subscribe
  }, [storeId]);

  return null;
}
